def coin_change(coins, amt):
  dp = [float('inf')]*(amt+1)
  dp[0] = 0
  for c in coins:
    for i in range(c, amt+1): dp[i] = min(dp[i], dp[i-c]+1)
  return dp[amt] if dp[amt] != float('inf') else -1
print(coin_change([1,2,5], 11))

