def knapsack(w, wt, val, n):
  dp = [[0]*(w+1) for _ in range(n+1)]
  for i in range(1, n+1):
    for j in range(w+1):
      if wt[i-1] <= j: dp[i][j] = max(val[i-1]+dp[i-1][j-wt[i-1]], dp[i-1][j])
      else: dp[i][j] = dp[i-1][j]
  return dp[n][w]
print(knapsack(50, [10,20,30], [60,100,120], 3))

